L["Removed %s."] = "%s removido."
L["%s is not on your list."] = "%s não está na sua lista."
L["%s (not in your spellbook now)"] = "%s (não está no seu grimório agora)"
L["%s (Manners now reminds you of it itself)"] = "%s (Manners agora lembra você dele por conta própria)"
L["Spells of your own (%d of %d):"] = "Magias suas (%d de %d):"
L["No spells of your own yet. Add one on Who to buff, under Add a spell of my own, or with /manners spell add <name or id>."] = "Ainda não há magias suas. Adicione uma em Quem recebe bônus, em Adicionar uma magia minha, ou com /manners spell add <nome ou id>."
L["Type /manners spell add <name or id>, or /manners spell remove <name or id>."] = "Digite /manners spell add <nome ou id>, ou /manners spell remove <nome ou id>."
L["your own buffs: held back -- you are in a fight."] = "seus próprios bônus: em espera -- você está em combate."
L["your own buffs: held back -- skipped for now."] = "seus próprios bônus: em espera -- pulados por enquanto."
L["your own buffs: held back -- the game will not say your name."] = "seus próprios bônus: em espera -- o jogo não informa seu nome."
L["your own buffs: held back -- you are on your never-offer list."] = "seus próprios bônus: em espera -- você está na sua lista de nunca oferecer."
