L["%s: none up -- %s is the one to use."] = "%s: nenhum ativo -- %s é o pergaminho a usar."
L["%s: none up -- %s is the one to cast."] = "%s: nenhum ativo -- %s é o feitiço a lançar."
L["%s: switched off (Don't remind me)."] = "%s: lembrete desativado (Não me lembrar)."
L["%s: a stone is in your bags or on your weapon already."] = "%s: já há uma pedra nas suas bolsas ou na sua arma."
L["%s: a healthstone is in your bags already."] = "%s: já há uma Pedra de Vida nas suas bolsas."
L["%s: %s needs a Soul Shard, and your bags hold none."] = "%s: %s precisa de um Fragmento de Alma, e não há nenhum nas suas bolsas."
L["%s: the weapon already carries a temporary enchant."] = "%s: a arma já tem um encantamento temporário."
L["%s: your off hand already carries a temporary enchant."] = "%s: sua mão secundária já tem um encantamento temporário."
L["%s: your main hand already carries a temporary enchant."] = "%s: sua mão principal já tem um encantamento temporário."
L["%s: a pet is out."] = "%s: há um mascote fora."
L["%s: %s is up."] = "%s: %s já está em você."
L["%s: you have no %s in your bags."] = "%s: você não tem %s nas bolsas."
L["%s: %s needs level %d."] = "%s: %s requer nível %d."
L["%s: %s needs Fishing %d."] = "%s: %s requer Pesca %d."
L["%s: there is no weapon in that hand."] = "%s: não há arma nessa mão."
L["%s: there is no weapon in your main hand."] = "%s: não há arma na sua mão principal."
L["%s: %s does not fit the weapon in that hand."] = "%s: %s não serve para a arma dessa mão."
L["%s: %s does not fit the weapon in your main hand."] = "%s: %s não serve para a arma da sua mão principal."
L["%s: Automatic, and your group role is not tank, so it is not offered."] = "%s: Automático, e sua função no grupo não é tanque, então o bônus não é oferecido."
L["%s: %s was pressed or skipped a moment ago."] = "%s: você clicou em %s ou pulou esse bônus há pouco."
L["%s: the game says %s cannot be cast right now."] = "%s: o jogo diz que não é possível lançar %s agora."
L["%s: %s waits until you dismount."] = "%s: %s espera você desmontar."
L["%s: Automatic has nothing it would pick."] = "%s: o Automático não tem nada para escolher."
L["%s: oils, stones, flasks, elixirs and scrolls are only offered in a dungeon or a raid."] = "%s: óleos, pedras, frascos, elixires e pergaminhos só são oferecidos em masmorras ou raides."
L["%s: oils, stones, food, flasks, elixirs and scrolls are only offered in a dungeon or a raid."] = "%s: óleos, pedras, comida, frascos, elixires e pergaminhos só são oferecidos em masmorras ou raides."
L["%s: you are at the level cap, with no experience left to gain."] = "%s: você está no nível máximo, sem mais experiência a ganhar."
L["%s: you are resting in the bag, or it is cooling down."] = "%s: você está descansando no saco, ou ele está em recarga."
L["%s: %s is ticked under Never remind me about."] = "%s: %s está marcado em “Nunca me lembrar de”."
L["%s: you are in another form, so it is not offered."] = "%s: você está em outra forma, então não é oferecido."
L["%s: %s goes on a shield, and there is none in your off hand."] = "%s: %s vai em um escudo, e não há nenhum na sua mão secundária."
L["%s: %s is only offered when you are alone, and you are in a group."] = "%s: %s só é oferecido quando você está sozinho, e você está em um grupo."
L["%s: tracking is not offered in a battleground or an arena."] = "%s: o rastreamento não é oferecido em um campo de batalha nem em uma arena."
L["%s: you are not swimming, so it is not offered."] = "%s: você não está nadando, então não é oferecido."
L["%s: %s waits until you stand still."] = "%s: %s espera até você parar."
L["%s: none out -- Manners brings one out of your pet journal itself."] = "%s: nenhum fora -- o Manners invoca um do seu Diário de Mascotes sozinho."
L["%s: you put your pet away, so none comes out until you bring one out yourself."] = "%s: você dispensou seu mascote, então nenhum sai até você mesmo invocar um."
L["%s: not in a dungeon, a raid, a battleground or an arena."] = "%s: não em masmorra, raide, campo de batalha nem arena."
L["%s: waits until you are not dead, flying, stealthed or casting."] = "%s: espera até você não estar morto, voando, furtivo nem lançando."
L["%s: waits until your pet battle is over."] = "%s: espera até a sua batalha de mascotes acabar."
L["%s: the game would not let Manners bring a pet out of your journal, so that is left to you."] = "%s: o jogo não deixou o Manners invocar um mascote do seu diário, então isso fica com você."
L["%s: the game will not say whether it is up, so it is not offered."] = "%s: o jogo não informa se o bônus está ativo, então ele não é oferecido."
L["your own buffs: held back -- you are in a city or an inn, and %s is off."] = "seus próprios bônus: em espera -- você está numa cidade ou estalagem, e a opção %s está desativada."
L["Also in cities and inns"] = "Também em cidades e estalagens"
L["your own %s comes first -- the buffs below wait until it has been cast."] = "seu próprio bônus (%s) vem primeiro -- os bônus abaixo esperam até ele ser lançado."
L["%s: switched off -- no scroll is offered."] = "%s: desativado -- nenhum pergaminho é oferecido."
L["Scrolls"] = "Pergaminhos"
L["%s: no timer -- never topped up."] = "%s: sem duração -- nunca é renovado."
L["%s: length unknown -- topped up at %s left, %s in a raid or dungeon."] = "%s: duração desconhecida -- renovado com %s restantes, e com %s em raide ou masmorra."
L["(%s as a group cast)"] = "(%s na versão em grupo)"
L["%s: lasts %s -- topped up at %s left, %s in a raid or dungeon, %s outside your group."] = "%s: dura %s -- renovado com %s restantes, com %s em raide ou masmorra e com %s fora do seu grupo."
L["%s: lasts %s -- topped up at %s left, %s in a raid or dungeon."] = "%s: dura %s -- renovado com %s restantes, e com %s em raide ou masmorra."
L["When a top-up is due"] = "Quando renovar"
L["When a top-up is due (top-ups are off)"] = "Quando renovar (renovação desativada)"
L["this class has no buffs to cast on other players."] = "esta classe não tem bônus para lançar em outros jogadores."
L["|cffff8080not during a fight|r -- the prompt cannot be put on screen while one is on. Try again when it ends."] = "|cffff8080não durante o combate|r -- o lembrete não pode aparecer na tela em combate. Tente de novo quando o combate terminar."
L["|cffffd100Manners|r is installed. It starts once you learn |cffffd100%s|r from your class trainer, and says hello properly then."] = "O |cffffd100Manners|r está instalado. Ele começa assim que você aprender |cffffd100%s|r com o instrutor da sua classe, e aí cumprimenta você direito."
L["You have learned |cffffd100%s|r, so Manners can start returning buffs."] = "Você aprendeu |cffffd100%s|r, então o Manners já pode começar a retribuir bônus."
L["|cffffd100Manners|r is installed, but this class has no buffs to cast on other players."] = "O |cffffd100Manners|r está instalado, mas esta classe não tem bônus para lançar em outros jogadores."
L["It is still worth keeping for an alt that does -- it will say hello again there."] = "Ainda vale a pena mantê-lo para um alt que tenha bônus -- ele vai se apresentar de novo lá."
L["With %s on, the prompt comes up when somebody could give you a buff you are missing, and a press asks them for it."] = "Com %s ativada, o lembrete aparece quando alguém poderia dar a você um bônus que falta, e um clique pede a essa pessoa."
L["It can also ask other players for a buff you are missing, one polite line at a press: tick %s in the options (|cffffd100/manners|r)."] = "Ele também pode pedir a outros jogadores um bônus que falta a você, uma frase educada por clique: marque %s nas opções (|cffffd100/manners|r)."
L["Ask people for a buff I'm missing"] = "Pedir a outros um bônus que me falta"
L["|cffffd100Manners|r is installed, but nothing will be offered to anybody: %s."] = "O |cffffd100Manners|r está instalado, mas nada será oferecido a ninguém: %s."
L["|cffffd100/manners welcome|r brings the rest of this back once that changes."] = "|cffffd100/manners welcome|r mostra o resto desta apresentação quando isso mudar."
L["Nothing to do: your own buffs are switched off under %s."] = "Nada a fazer: seus próprios bônus estão desativados na seção %s."
L["Myself"] = "Eu"
L["|cffffd100Manners|r puts your own buffs on a small prompt when none of them is up -- your class has none for other players. Clicking the prompt casts it on you."] = "O |cffffd100Manners|r põe seus próprios bônus num pequeno lembrete quando nenhum deles está ativo -- sua classe não tem nenhum para outros jogadores. Clicar no lembrete lança o bônus em você."
L["|cffffd100Manners|r puts your own buffs on a small prompt when none of them is up; nothing is offered to anybody else: %s. Clicking the prompt casts it on you."] = "O |cffffd100Manners|r põe seus próprios bônus num pequeno lembrete quando nenhum deles está ativo; nada é oferecido a mais ninguém: %s. Clicar no lembrete lança o bônus em você."
L["Only one person can have %s at a time, so it goes to one member of your group who is not of your class, and only while none of yours is on anybody in it."] = "Só uma pessoa pode ter %s por vez, então vai para um membro do seu grupo que não seja da sua classe, e só enquanto nenhum dos seus estiver em ninguém nele."
L["Only one person can have %s at a time, so it goes to a tank of your group (the tank role, or main tank in a raid), and only while none of yours is on anybody in it."] = "Só uma pessoa pode ter %s por vez, então vai para um tanque do seu grupo (a função de tanque, ou tanque principal em uma raide), e só enquanto nenhum dos seus estiver em ninguém nele."
L["|cffffd100Manners|r puts anybody in your group who is missing your |cffffd100%s|r -- or who has just buffed you -- on a small prompt. Clicking the prompt casts it."] = "O |cffffd100Manners|r põe quem do seu grupo estiver sem o seu bônus |cffffd100%s|r -- ou tiver acabado de dar bônus a você -- num pequeno lembrete. Clicar no lembrete lança o bônus."
L["|cffffd100Manners|r puts anybody in your group who is missing your |cffffd100buff|r -- or who has just buffed you -- on a small prompt. Clicking the prompt casts it."] = "O |cffffd100Manners|r põe quem do seu grupo estiver sem o seu |cffffd100bônus|r -- ou tiver acabado de dar bônus a você -- num pequeno lembrete. Clicar no lembrete lança o bônus."
L["|cffffd100Manners|r puts anybody who buffs you -- and any stranger nearby who is missing one of yours -- on a small prompt. Clicking the prompt buffs them."] = "O |cffffd100Manners|r põe quem der bônus a você -- e qualquer desconhecido por perto que esteja sem um dos seus -- num pequeno lembrete. Clicar no lembrete dá o bônus a quem estiver nele."
L["|cffff8080Friendly nameplates are off|r, so Manners cannot tell who a stranger is: a passer-by who buffs you, or who is missing your buff, never comes up on the prompt. %s on %s (|cffffd100/manners|r) turns them on."] = "|cffff8080As placas de identificação aliadas estão desativadas|r, então o Manners não consegue saber quem é um desconhecido: um transeunte que der bônus a você, ou que esteja sem o seu, nunca aparece no lembrete. %s em %s (|cffffd100/manners|r) as ativa."
L["The one thing that is not automatic: |cffffd100/manners macro|r or |cffffd100Put Manners on an action bar|r in the options puts a macro on your cursor for your bars, or bind a key under Options > Keybindings > Manners."] = "A única coisa que não é automática: |cffffd100/manners macro|r ou |cffffd100Colocar o Manners numa barra de ações|r nas opções coloca uma macro no seu cursor para as suas barras, ou defina uma tecla em Opções > Teclas de Atalho > Manners."
L["|cffff8080It is switched off on this profile|r, so no prompt will appear -- |cffffd100/manners on|r when you want it."] = "|cffff8080Ele está desativado neste perfil|r, então nenhum lembrete vai aparecer -- use |cffffd100/manners on|r quando quiser."
L["The prompt is on screen now, with somebody real on it already. |cffffd100/manners welcome|r brings this back."] = "O lembrete já está na tela, com alguém de verdade nele. |cffffd100/manners welcome|r mostra isto de novo."
L["That is the prompt, with a pretend name on it. |cffffd100/manners welcome|r brings this back."] = "Este é o lembrete, com um nome fictício. |cffffd100/manners welcome|r mostra isto de novo."
L["does not exist (or its existence is withheld)"] = "não existe (ou sua existência está oculta)"
L["withheld: %s"] = "oculto: %s"
L["this buff is not readable here"] = "este bônus não pode ser lido aqui"
L["%s has no unit token right now, so {unit} cannot be filled"] = "%s não tem token de unidade agora, então {unit} não pode ser preenchido"
L["until you log out"] = "até você sair do jogo"
L["until %s"] = "até %s"
L["1 minute"] = "1 minuto"
L["%d minutes"] = "%d minutos"
L["snoozed until you log out -- though Manners is switched off, so no prompt appears either way."] = "em soneca até você sair do jogo – o Manners está desligado, então nenhum aviso aparece de qualquer jeito."
L["snoozed until you log out. In a fight the prompt stays as the fight found it, and follows the snooze once this one ends. |cffffd100/manners snooze off|r ends it."] = "em soneca até você sair do jogo. Em combate o aviso fica como o combate o encontrou e segue a soneca quando esta acabar. |cffffd100/manners snooze off|r encerra a soneca."
L["snoozed until you log out. The prompt is unlocked, so it stays up to be dragged and casts nothing; once you lock it, it stays away. |cffffd100/manners snooze off|r ends it."] = "em soneca até você sair do jogo. O aviso está destravado, então fica na tela para ser arrastado e não lança nada; quando você o travar, ele some. |cffffd100/manners snooze off|r encerra a soneca."
L["snoozed until you log out or reload -- no prompt until then. |cffffd100/manners snooze off|r ends it."] = "em soneca até você sair do jogo ou recarregar – sem aviso até lá. |cffffd100/manners snooze off|r encerra a soneca."
L["snoozed for %s, %s -- though Manners is switched off, so no prompt appears either way."] = "soneca de %s, %s -- mas o Manners está desativado, então nenhum lembrete aparece de qualquer forma."
L["snoozed for %s, %s. In a fight the prompt stays as the fight found it, and follows the snooze once this one ends. |cffffd100/manners snooze off|r ends it early."] = "soneca de %s, %s. Em combate, o lembrete fica como estava quando o combate começou e segue a soneca quando este combate terminar. |cffffd100/manners snooze off|r encerra a soneca antes."
L["snoozed for %s, %s. The prompt is unlocked, so it stays up to be dragged and casts nothing; once you lock it, it stays away until the snooze ends. |cffffd100/manners snooze off|r ends it early."] = "soneca de %s, %s. O lembrete está destravado, então fica na tela para ser arrastado e não lança nada; quando você travá-lo, ele some até a soneca terminar. |cffffd100/manners snooze off|r encerra a soneca antes."
L["snoozed for %s -- no prompt %s. |cffffd100/manners snooze off|r ends it early."] = "soneca de %s -- nenhum lembrete %s. |cffffd100/manners snooze off|r encerra a soneca antes."
L["the snooze is over, but Manners is switched off -- |cffffd100/manners on|r to see the prompt again."] = "a soneca acabou, mas o Manners está desativado -- |cffffd100/manners on|r para ver o lembrete de novo."
L["the snooze is over -- the prompt can appear again once this fight ends."] = "a soneca acabou -- o lembrete pode aparecer de novo quando este combate terminar."
L["the snooze is over -- the prompt can appear again."] = "a soneca acabou -- o lembrete pode aparecer de novo."
L["not snoozed -- the prompt is free to appear."] = "sem soneca -- o lembrete está livre para aparecer."
L["there is nothing to import -- paste a settings string that starts with MNR1:."] = "não há nada para importar -- cole um texto de configurações que comece com MNR1:."
L["that is not a Manners settings string -- one starts with MNR1:."] = "isso não é um texto de configurações do Manners -- os do Manners começam com MNR1:."
L["that is far longer than any Manners settings string, so it was not read."] = "isso é bem mais longo que qualquer texto de configurações do Manners, então não foi lido."
L["that string was made by a newer version of Manners -- update the addon to read it."] = "esse texto foi feito por uma versão mais nova do Manners -- atualize o addon para lê-lo."
L["that string is incomplete or has been changed -- copy it again in one piece, and paste a long one into the box under Share as text (%s)."] = "esse texto está incompleto ou foi alterado -- copie de novo, inteiro, e cole um texto longo na caixa em Compartilhar como texto (%s)."
L["that string is damaged -- part of it is not a setting Manners can read. Copy it again in one piece."] = "esse texto está danificado -- parte dele não é uma configuração que o Manners consiga ler. Copie de novo, inteiro."
L["that string gives %s a value it cannot have, so nothing was changed."] = "esse texto dá a %s um valor que não é permitido, então nada foi alterado."
L["settings imported -- every one of them is the default."] = "configurações importadas -- todas estão no padrão."
L["settings imported -- 1 differs from the defaults."] = "configurações importadas -- 1 difere do padrão."
L["settings imported -- %d differ from the defaults."] = "configurações importadas -- %d diferem do padrão."
L["1 setting from a newer version of Manners was left out."] = "1 configuração de uma versão mais nova do Manners ficou de fora."
L["%d settings from a newer version of Manners were left out."] = "%d configurações de uma versão mais nova do Manners ficaram de fora."
L["The string had speaking a line when you buff switched on. That is left off, because it talks to other players: switch it on under What I say if you want it."] = "O texto trazia ativada a opção de dizer uma frase ao dar bônus. Ela fica desativada, porque fala com outros jogadores: ative-a na aba O que eu digo se quiser."
L["The string had /thank people who buff me switched on. That is left off, because everybody near you sees it: switch it on under What I say if you want it."] = "O texto trazia ativada a opção Fazer /thank para quem me dá bônus. Ela fica desativada, porque todos por perto a veem: ative-a na aba O que eu digo se quiser."
L["The string had whispering a thank-you to people you can't buff back switched on. That is left off, because it talks to other players: switch it on under What I say if you want it."] = "O texto trazia ativada a opção de sussurrar um obrigado a quem você não pode retribuir. Ela fica desativada, porque fala com outros jogadores: ative-a na aba O que eu digo se quiser."
L["The string had thanking people even when you can't see who it was switched on. That is left off, because everybody near you sees it: switch it on under What I say if you want it."] = "O texto trazia ativada a opção de agradecer mesmo sem ver quem foi. Ela fica desativada, porque todos por perto a veem: ative-a na aba O que eu digo se quiser."
L["The string had asking people for a buff switched on. That is left off, because it talks to other players: switch it on under Who to buff if you want it."] = "O texto trazia ativada a opção de pedir bônus a outros. Ela fica desativada, porque fala com outros jogadores: ative-a na aba Quem recebe bônus se quiser."
L["What you say when you buff, and where, is kept as you had it, because you have speaking switched on."] = "O que você diz ao dar bônus, e onde, continua como estava, porque você está com a fala ativada."
L["How you ask for a buff, and where, is kept as you had it, because you have asking switched on."] = "Como você pede um bônus, e onde, continua como estava, porque você está com o pedido de bônus a outros ativado."
L["The prompt's look changes when this fight ends."] = "O visual do lembrete muda quando este combate terminar."
L["|cffffd100/manners import undo|r puts your old settings back."] = "|cffffd100/manners import undo|r restaura suas configurações antigas."
L["nothing to undo -- no settings have been imported on this profile this session."] = "nada para desfazer -- nenhuma configuração foi importada neste perfil nesta sessão."
L["nothing to undo on this profile -- the last import was made on profile %s. Switch back to it to undo it."] = "nada para desfazer neste perfil -- a última importação foi feita no perfil %s. Volte para ele para desfazê-la."
L["nothing to undo on this profile -- the last import was made on another one. Switch back to it to undo it."] = "nada para desfazer neste perfil -- a última importação foi feita em outro perfil. Volte para ele para desfazê-la."
L["your settings from before the import are back. The prompt's look changes when this fight ends."] = "suas configurações de antes da importação voltaram. O visual do lembrete muda quando este combate terminar."
L["your settings from before the import are back."] = "suas configurações de antes da importação voltaram."
